const pronouns=[pair('ich','я','I','pronoun'),pair('du','ти','you','pronoun'),pair('er','він','he','pronoun'),pair('sie','вона','she','pronoun'),pair('wir','ми','we','pronoun'),pair('ihr','ви (до кількох людей)','you (plural)','pronoun')];
const verbs=[pair('lernen','вчитися','to learn','verb'),pair('machen','робити','to do','verb'),pair('wohnen','проживати','to reside','verb'),pair('spielen','грати','to play','verb'),pair('gehen','йти','to go','verb'),pair('hören','чути / слухати','to hear / listen','verb')];
