 {id:0,key:'deutsch16_journey_v1',title:['Острів загубленого компаса','Island of the lost compass'],theme:['Я та мої дії','Me and my actions'],subtitle:['Дев’ять уроків: від привітання на кораблі до загубленого компаса.','Nine lessons: from greetings aboard ship to the lost compass.'],map:'island-eight',relic:'treasure',relicName:['Старий компас','The old compass'],finalTitle:['Схованка старого компаса','The old compass cache'],finalLabel:['Схованка скарбів','Treasure cache'],finalAction:['Шукати скарб','Find the treasure'],lessons:journeyLessons,stops:expeditionStops,intro:['Досліджуй острів, вивчай німецьку й збирай печатки. У фінальній схованці на тебе чекає старий компас.','Explore the island, learn German and collect seals. An old compass awaits in the final cache.'],found:['Компас знайдено! Його стрілка веде до острова мешканців.','Compass found! Its needle points to the residents’ island.']},
 {id:1,key:'deutsch16_journey_village_v1',title:['Знайомство з мешканцями','Meet the island residents'],theme:['Бути, мати та знайомитися','Be, have and meet people'],subtitle:['Сім уроків: від ввічливої зустрічі в гавані до маяка.','Seven lessons: from a polite harbour welcome to the lighthouse.'],map:'village-lagoon-20261024',relic:'village-key',relicName:['Ключ від маяка','The lighthouse key'],finalTitle:['Зустріч біля маяка','Meeting at the lighthouse'],finalLabel:['Фінальна місія','Final mission'],finalAction:['Зустріти хранителя','Meet the keeper'],lessons:villageData.lessons.map((l,i)=>({stage:villageStageStart+i,title:l.title,goal:l.goal})),stops:villageData.stops,intro:['Компас привів команду до приморського містечка. Питай, знайомся й допоможи хранителю знайти ключ від маяка.','The compass led the team to a seaside village. Ask questions, meet people and help the keeper find the lighthouse key.'],found:['Ключ знайдено! Мешканці довірили тобі маяк. Друга пригода завершена.','Key found! The residents have trusted you with their lighthouse. Your second adventure is complete.']},
 {id:2,key:'deutsch16_journey_gear_v1',title:['Острів спорядження','Equipment island'],theme:['Речі, числа та прохання','Objects, numbers and requests'],subtitle:['Сім уроків: від складу експедиції до спорядженого рюкзака.','Seven lessons: from the store to a packed backpack.'],map:'gear-island-20261028',relic:'gear-route-scroll',relicName:['Карта нового маршруту','The new route map'],finalTitle:['Рюкзак для нової пригоди','Backpack for a new adventure'],finalLabel:['Зібрати рюкзак','Pack the backpack'],finalAction:['Почати фінальну місію','Start the final mission'],lessons:gearData.lessons.map((l,i)=>({stage:gearStageStart+i,title:l.title,goal:l.goal})),stops:gearData.lessons.map(l=>l.stop),intro:['Світло маяка відкрило шлях до скелястого острова. Познайомся з командою складу й підготуй спорядження для нового маршруту.','The lighthouse revealed a rocky island. Meet its team and collect equipment for a new route.'],found:['Спорядження зібрано! Карта нового маршруту твоя.','Equipment collected! The new route map is yours.']}
