function shadowingOpen(j){if(j.final||j.island!==activeIsland||j.island===1&&j.index===5||j.island===2&&j.index===6)return false;const cards=lessonCards(j);if(!cards?.length)return false;cancel();window.DEUTSCH_SHADOWING.mount({root,shell,t,cards,id:j.island+':'+(j.entry||j.index),art,meaning,exit:()=>journeyOpen(j.entry||j.index)});return true}
