function lessonCounter(s,item){if(s.daily)return t('Повторення','Review')+' · '+(s.index+1)+' / '+s.queue.length;if(!s.lessonMode)return t('Завдання','Task')+' '+(s.journey?s.queue.slice(0,s.index+1).filter(q=>!!q.assessment===!!item.assessment).length:s.index+1)+' / '+(s.journey?s.queue.filter(q=>!!q.assessment===!!item.assessment).length:s.queue.length);if(item.retry)return t('Виправлення помилок','Correct mistakes')+' · '+t('спроба','attempt')+' '+(cycle().status(s.results).find(r=>cycle().id(r.task)===cycle().id(item))?.attempts+1||1)+' / 3';if(s.lessonMode==='test')return t('Тест','Test')+' · '+(s.index+1)+' / '+s.queue.length;return t('Етап','Stage')+' '+(item.round+1)+' / 5 · '+label(item.type)+' · '+(s.queue.slice(0,s.index+1).filter(q=>q.round===item.round&&!q.retry).length)+' / '+s.batch.length}
function trainingFinish(){const s=session,mic=!s.micUnavailable&&!!(window.SpeechRecognition||window.webkitSpeechRecognition),next=cycle().corrections(s.results,mic);if(next.length){s.queue.push(...next);show();return}pause();s.finished=true;const rows=cycle().status(s.results),unresolved=rows.filter(r=>!r.ok),d=trainingState();d.lessons[trainingId(s.journey)]={completed:true,at:Date.now(),unresolved:unresolved.map(r=>({de:r.task.c.de,type:r.task.type,attempts:r.attempts,wrong:r.wrong,skipped:r.skipped}))};profileStorage.setItem(trainingKey,JSON.stringify(d));shell(`<section class="lesson-training-summary"><h1>${t('Тренування завершено','Training complete')}</h1><p>${t('Усі фрази пройдено через п’ять етапів. Тепер можна окремо перевірити знання й отримати печатку за тест.','Every phrase has gone through five stages. Now take the separate test to check your knowledge and earn the lesson seal.')}</p><p>${t('Виправлено та засвоєно в цьому проходженні','Completed successfully in this session')}: ${rows.filter(r=>r.ok).length} / ${s.batch.length*5}</p>${lessonUnresolved(unresolved)}<div class="journey-result-buttons"><button class="btn primary" id="alStartTest">${t('Пройти тест','Take the test')} · ${s.batch.length*3}</button><button class="btn secondary" id="alTrainAgain">${t('Повторити тренування','Repeat training')}</button>${isMarketJourney(s.journey)?`<button type="button" class="btn secondary" id="alBennoTalk">${t('Поговорити з Бенно','Talk with Benno')}</button>`:''}${s.journey.island===1&&s.journey.index===5?`<button class="btn secondary" id="alKarlTalk">${t('Поговорити з Карлом','Talk with Karl')}</button>`:''}<button class="btn secondary" id="alDone">${t('До мапи','Map')}</button></div></section>`);root.querySelector('#alStartTest').onclick=()=>lessonRun(s.journey,'test');root.querySelector('#alTrainAgain').onclick=()=>lessonRun(s.journey,'training');root.querySelector('#alDone').onclick=render;const k=root.querySelector('#alKarlTalk');if(k)k.onclick=karlConversationOpen;const b=root.querySelector('#alBennoTalk');if(b)b.onclick=bennoConversationOpen}
function lessonErrorRule(s,c){const rule=stages.find(st=>st.id===s.stageId)?.rule;if(rule)return local(rule);const tips={'Hallo!':['Коротке привітання з другом.','A short greeting for a friend.'],'Tschüss!':['Коротке прощання з другом.','A short goodbye to a friend.'],'Guten Morgen!':['Ранкове привітання.','A morning greeting.'],'Guten Tag!':['Нейтральне денне привітання.','A neutral daytime greeting.'],'Guten Abend!':['Вітаємося ввечері; перед сном бажаємо Gute Nacht!','Greet people in the evening; before sleep say Gute Nacht!'],'Auf Wiedersehen!':['Ввічливе прощання.','A polite goodbye.'],'Danke!':['Дякуємо за допомогу чи подарунок.','Thank someone for help or a gift.'],'Bitte!':['У проханні — «будь ласка», у відповідь на Danke! — «прошу».','In a request: “please”; after Danke!: “you’re welcome”.'],'Ja.':['Погоджуємося: «так».','Agree: “yes”.'],'Nein.':['Заперечуємо: «ні».','Disagree: “no”.'],"Wie geht's?":['Запитуємо, як справи у співрозмовника.','Ask how the other person is.'],'Gut, danke.':['Відповідаємо на запитання про справи: «Добре, дякую».','Answer a question about how you are: “Fine, thank you”.']};return local(tips[c.de]||['Порівняй фразу з перекладом і прослухай її ще раз.','Compare the phrase with its translation and listen again.'])}
function lessonUnresolved(rows){return rows.length?`<aside class="journey-recap"><h2>${t('Ще потренувати','Practise some more')}</h2>${rows.map(r=>`<p><b lang="de">${esc(r.task.c.de)}</b> · ${label(r.task.type)} · ${r.skipped?t('пропущено, не зараховано як засвоєне','skipped, not marked mastered'):t('три невдалі спроби — відповідь показана в поясненні','three unsuccessful attempts — see the answer in feedback')}</p>`).join('')}</aside>`:''}
function testCorrections(){const s=session,initial=s.results.filter(r=>r.assessment&&!r.retry),correct=initial.filter(r=>r.ok&&!r.skipped).length;s.frozenResult={correct,total:initial.length,percent:Math.round(correct/initial.length*100)};const next=cycle().corrections(initial,false);if(!next.length)return;const b=document.createElement('button');b.type='button';b.className='btn secondary';b.id='alCorrectMistakes';b.textContent=t('Виправити помилки — оцінка не зміниться','Correct mistakes — the score stays fixed');b.onclick=()=>{s.lessonMode='repair';s.finished=false;s.queue.push(...next);s.index=s.queue.length-next.length;show()};root.querySelector('.journey-result-buttons').prepend(b)}
function repairFinish(){const s=session,next=cycle().corrections(s.results,false);if(next.length){s.queue.push(...next);show();return}pause();s.finished=true;const rows=cycle().status(s.results).filter(r=>!r.ok),r=s.frozenResult;shell(`<section class="lesson-repair-summary"><h1>${t('Повторення завершено','Corrections complete')}</h1><p>${t('Початкова оцінка тесту','Original test score')}: ${r.correct} / ${r.total} · ${r.percent}%</p><p>${t('Виправлення не змінюють оцінку. Для нового результату пройди інший випадковий тест.','Corrections do not change your score. Take a new randomized test for a new result.')}</p>${lessonUnresolved(rows)}<button class="btn primary" id="alNewTest">${t('Новий тест','New test')}</button><button class="btn secondary" id="alDone">${t('До мапи','Map')}</button></section>`);root.querySelector('#alNewTest').onclick=()=>lessonRun(s.journey,'test');root.querySelector('#alDone').onclick=render}
