function entryFinish(){pause();const s=session;s.finished=true;const entry=s.journey.entry,courtesy=entry==='courtesy',g=window.DEUTSCH_GREETINGS,old=(courtesy?g.readCourtesy():g.read())||{},tests=s.results.filter(r=>r.assessment),correct=tests.filter(r=>r.ok&&!r.skipped).length,total=s.queue.filter(q=>q.assessment).length,pct=Math.round(correct/total*100),passed=correct>=Math.ceil(total*.8);profileStorage.setItem(courtesy?g.courtesyKey:g.key,JSON.stringify({...old,version:3,passed:!!old.passed||passed,best:Math.max(old.best||0,correct/total*8),last:correct/total*8,lastCorrect:correct,assessmentCount:total,lastPercent:pct,attempts:(old.attempts||0)+1}));shell(`<button class="btn secondary" id="greetingBack">${t('← До мапи','← Map')}</button><section class="greeting-result" data-greeting-result="${passed?'passed':'retry'}" data-ship-chapter="${entry}"><div class="tag">${entryTitle(entry)}</div><h1>${passed?t('Урок пройдено!','Lesson passed!'):t('Ще трохи практики','A little more practice')}</h1><p class="journey-score">${correct} / ${total} · ${pct}%</p><p>${t('Тест перевіряє всі фрази: по три запитання на кожну. Для проходження потрібно щонайменше 80%.','The test covers every phrase with three questions each. Pass with at least 80%.')}</p>${(courtesy?g.readCourtesy():g.read())?.passed?`<p>✓ ${t('Печатку уроку збережено','Lesson seal saved')}</p>`:''}<div class="journey-result-buttons"><button class="btn primary" id="greetingContinue">${courtesy?t('До уроку 2 · команда на причалі','Lesson 2 · team at the landing'):t('До уроку 2 · висадка на берег','Lesson 2 · land on the shore')}</button><button class="btn secondary" id="greetingRetry">${t('Повторити','Try again')}</button></div></section>${teamEntryReward(s.journey,pct,old.best===8)}`);root.querySelector('#greetingBack').onclick=render;root.querySelector('#greetingContinue').onclick=()=>journeyOpen(0);root.querySelector('#greetingRetry').onclick=()=>courtesy?courtesyOpen():greetingsOpen()}
function greetingsOpen(camp=false){if(activeIsland!==0)return;cancel();window.DEUTSCH_GREETINGS.mount({root,shell,t,camp,courtesy:false,mentorNote:camp?'':teamMasteryPreview({entry:'greetings',island:0}),practice:()=>entryBegin(false),repeat:()=>shadowingOpen({entry:'greetings',index:-1,island:0}),test:()=>entryBegin(false,'test'),canTest:lessonEligible({entry:'greetings',island:0}),exit:render,next:()=>journeyOpen(camp?1:0)})}
