function routeProgress(id=activeIsland){if(id===2){const c=islands[2],d=islandProgress(2);return c.lessons.map((_,i)=>({id:i,number:i+1,name:c.stops[i].name,earned:!!d.lessons[i]?.passed,perfect:d.lessons[i]?.best===100}))}const c=islands[id],d=islandProgress(id),items=c.lessons.map((_,i)=>({id:i,number:i+2,name:c.stops[i].name,earned:!!d.lessons[i]?.passed,perfect:d.lessons[i]?.best===100}));const g=id===0?window.DEUTSCH_GREETINGS.read():window.DEUTSCH_GREETINGS.readCourtesy();items.unshift({id:id===0?'greetings':'courtesy',number:1,name:id===0?['Вирушаємо у подорож','Let’s begin our journey']:['Гавань знайомств','Welcome harbour'],earned:!!g?.passed,perfect:g?.best===8});return items}
