function voyagePin(){if(activeIsland===2)return '';const r=routeProgress()[0],ship=activeIsland===0;return `<li class="journey-stop expedition-stop expedition-voyage ${r.earned?'is-complete':'is-current'} ${r.perfect?'is-perfect':''}" style="--pin-x:50%;--pin-y:5.1%"><button type="button" class="expedition-pin expedition-voyage-link" id="${ship?'greetingOpen':'courtesyOpen'}" data-route-lesson="${r.id}" aria-label="${esc(t('Урок 1. ','Lesson 1. ')+local(r.name)+'. '+(ship?t('Привітання та прощання на кораблі.','Greetings and goodbyes aboard ship.'):t('Дякуємо та розмовляємо ввічливо з Ліною.','Thank Lina and speak politely.')))}${r.earned?t(' Тест складено.',' Test passed.'):''}" ${r.earned?'':'aria-current="step"'}><img class="voyage-ship-art ${ship?'':'arrival-quay-art'}" src="${ship?'assets/illustrations/places/exp_47.png':'assets/illustrations/expedition/arrival-quay-20261024.webp'}" alt="" decoding="async"><span class="voyage-stop-copy"><span class="expedition-pin-number">${r.perfect?'★':r.earned?'✓':1}</span><span class="expedition-pin-label">${local(r.name)}</span></span></button></li>`}
function greetingBridge(j,state){if(!j||j.final)return '';if(j.island===0&&j.index===1&&state==='welcome')return `<aside class="greeting-bridge"><p>${t('Увечері повернемося до табору. Бруно навчить відрізняти вечірнє привітання від побажання перед сном.','We will return to camp in the evening. Bruno will help you distinguish an evening greeting from a wish before sleep.')}</p><button class="btn secondary" id="campGreetings">${t('Вечір у таборі · 2 фрази','Evening at camp · 2 phrases')}</button></aside>`;if(j.island!==1)return '';const hello=j.index===0?'Guten Morgen!':j.index===4?'Guten Abend!':'Guten Tag!',phrase=state==='welcome'?hello:'Auf Wiedersehen!';return `<aside class="greeting-bridge" data-greeting-bridge><p>${state==='welcome'?(j.index===0?t('Ранок у порту. Пригадай берег: спочатку вітаємося, потім знайомимося.','Morning at the harbour. Remember the shore: first greet people, then introduce yourself.'):j.index===4?t('Вечір у гостях в Емми. Починаємо розмову з вечірнього привітання.','Evening at Emma’s home. Begin with an evening greeting.'):t('День у містечку. Спочатку вітаємося, потім розмовляємо.','Daytime in the village. Greet people before starting the conversation.')):t('Розмову завершуємо ввічливим прощанням.','Close the conversation with a polite goodbye.')}</p><button class="btn secondary" lang="de" data-journey-greeting="${phrase}">${phrase} · ${t('Послухати','Listen')}</button></aside>${villageConversationBridge(j,state)}`}

function villageConversationBridge(j,state){if(state!=='welcome'||j?.island!==1||j.final)return '';if(j.index===0&&foxConversationDone())return `<p class="greeting-bridge" data-fox-handoff>${t('Ти вже репетирував знайомство з Лисом. Тепер Ліна допоможе сказати, хто тут і хто готовий: Ich bin hier.','You rehearsed introductions with Fox. Now Lina will help you say who is here and ready: Ich bin hier.')}</p>`;const phrases=window.DEUTSCH_FOX_CONVERSATION.phrases;const line=p=>`<div class="fox-lesson-line"><strong lang="de">${p.de}</strong><span>${en()?p.en:p.ua}</span><button type="button" class="btn secondary" data-journey-greeting="${p.de}">${t('Послухати','Listen')}</button></div>`;return j.index===2?`<section class="village-conversation" data-conversation-link="questions"><h3>${t('Додаємо запитання до розмови','Add a question to the conversation')}</h3>${line(phrases.ask)}<aside class="later-politeness" data-polite-later><h4>${t('Тепер — ввічливе звертання','Now — a polite way to get attention')}</h4><img class="greeting-art" src="assets/illustrations/greetings/09.png" alt=""><p><strong lang="de">Entschuldigung!</strong> — ${t('Перепрошую!','Excuse me!')}</p><p>${t('На площі мешканці зайняті. Спочатку приверни увагу, а потім постав запитання.','The residents in the square are busy. Get their attention before asking a question.')}</p><button type="button" class="btn secondary" data-journey-greeting="Entschuldigung!">${t('Послухати','Listen')}</button></aside></section>`:j.index===4?`<section class="village-conversation" data-conversation-link="introduction"><h3>${t('Знайомство з Еммою · ти граєш Олексія','Meeting Emma · you play Oleksii')}</h3>${line(phrases.ask)}${line(phrases.name)}<p>${t('Застосуй репетицію з Лисом у справжній зустрічі з мешканцями.','Use your rehearsal with Fox when meeting the residents.')}</p></section>`:''}

function journeyLoad(){return islandProgress(activeIsland)}
function journeyQueue(index,final=false){
 const task=(c,type,extra={})=>({...extra,c,type:c.replyTo&&type==='listen'?'de':type,...(c.replyTo&&['de','write','listen'].includes(type)?{dialoguePrompt:c.replyTo}:{})});
 if(final){const used=new Set(),queue=[];for(const i of journeyLessons.map((_,i)=>i).reverse()){const cards=shuffle(stages[journeyLessons[i].stage].cards).filter(c=>!used.has(c.id)).slice(0,3);if(cards.length!==3)throw Error('Insufficient unique final material');cards.forEach((c,j)=>{used.add(c.id);queue.push(task(c,['de','listen','write'][(i+j)%3],{assessment:true,lessonIndex:i}))})}if(activeIsland===0)shuffle(greetingCards).slice(0,3).forEach((c,i)=>queue.push(task(c,['de','listen','write'][i],{assessment:true,lessonIndex:'greetings',chapter:'greetings'})));if(activeIsland===1)shuffle(courtesyCards).slice(0,3).forEach((c,i)=>queue.push(task(c,['de','listen','write'][i],{assessment:true,lessonIndex:'courtesy',chapter:'courtesy'})));return shuffle(queue)}
 return lessonPlan(stages[journeyLessons[index].stage].cards,'training');
}
function journeyOpen(index=0,final=false){if(index==='greetings'&&activeIsland===0&&!final){greetingsOpen();return}if(index==='courtesy'&&activeIsland===1&&!final){courtesyOpen();return}if(!final&&(!Number.isInteger(index)||!journeyLessons[index]))return;const batch=final?[...new Map([...journeyLessons.flatMap(l=>stages[l.stage].cards),...(activeIsland===0?greetingCards:activeIsland===1?courtesyCards:[])].map(c=>[c.id,c])).values()]:stages[journeyLessons[index].stage].cards;begin(batch,final?null:stages[journeyLessons[index].stage].id,true,journeyQueue(index,final),{index,final,island:activeIsland,...(!final?{mode:'training'}:{})});root.style.scrollMarginTop=((document.querySelector('.mode-tabs')?.getBoundingClientRect().height||80)+20)+'px';root.scrollIntoView({block:'start',behavior:'auto'})}

function journeyMap(){try{cancel();const c=island(),d=journeyLoad(),p=plan(),rewards=expeditionRewards(d),route=routeProgress(),done=route.filter(s=>s.earned).length,voyagePending=activeIsland<2&&!route[0].earned,recommended=journeyLessons.findIndex((l,i)=>!d.lessons[i]?.passed),target=recommended<0?0:recommended;
shell(`${islandPicker()}<header class="expedition-heading"><div class="tag">${t('Експедиція','Expedition')} 0${activeIsland+1} · ${local(c.theme)}</div><h1>${local(c.title)}</h1><p>${local(c.subtitle)}</p></header>
<section class="expedition-invitation">${expeditionImage('fox','expedition-guide')}<div><strong>${activeIsland===0?t('Мапа справжня. Вирушаємо?','The map is real. Shall we go?'):t('Компас привів нас до мешканців!','The compass brought us to the residents!')}</strong><p>${local(c.intro)}</p><button class="btn primary" id="alStart">${t(recommended<0?'Повторити експедицію':'Продовжити експедицію',recommended<0?'Revisit expedition':'Continue expedition')}</button></div></section>
${dailyPanel()}
<div class="expedition-map-head"><span><b>${done} / ${route.length}</b> ${t('печаток зібрано','seals collected')}</span><span>${t('Будь-яке місце можна відкрити','Every place is open')}</span><button type="button" class="motion-toggle" data-motion-toggle aria-pressed="true">${t('Анімації увімкнено','Animations on')}</button></div>
<div class="expedition-board ${activeIsland===2?'is-gear':activeIsland===1?'is-village has-arrival'+(d.final?.passed?' is-lighthouse-lit':''):'has-voyage'}">${expeditionImage(c.map,'expedition-island',local(c.title))}${activeIsland===1&&d.final?.passed?'<span class="lighthouse-beacon" aria-hidden="true"></span>':''}<ol class="expedition-pins" aria-label="${t('Маршрут навчання','Learning route')}">${voyagePin()}${journeyLessons.map((l,i)=>{const r=rewards.seals[i],place=expeditionStops[i];return `<li class="journey-stop expedition-stop ${r.earned?'is-complete':''} ${i===recommended&&!voyagePending?'is-current':''} ${r.perfect?'is-perfect':''}" style="--pin-x:${place.x}%;--pin-y:${mapY(place.y)}%"><button type="button" class="expedition-pin" data-journey-lesson="${i}" aria-label="${esc(t('Урок','Lesson')+' '+lessonNumber(i)+'. '+local(place.name)+'. '+local(l.title)+(r.perfect?t('. 100%, відзнака майстерності','. 100%, mastery award'):r.earned?t('. Тест складено','. Test passed'):''))}" ${i===recommended&&!voyagePending?'aria-current="step"':''}><span class="expedition-pin-number">${r.perfect?'★':r.earned?'✓':lessonNumber(i)}</span><span class="expedition-pin-label">${activeIsland===2?local(gearData.mapLabels[i]):activeIsland===1?local(window.DEUTSCH_VILLAGE_MENTORS.mapLabels[i]):local(place.name)}</span></button></li>`}).join('')}<li class="journey-finale expedition-cache"><button type="button" id="journeyFinal" aria-label="${esc(local(c.finalLabel)+'. '+t('Фінальне випробування','Final challenge')+', '+finalCount()+' '+t('завдань','tasks'))}"><span class="expedition-pin-number">${rewards.artifact?'✓':'?'}</span><span class="expedition-pin-label">${local(c.finalLabel)}</span></button></li></ol></div>
<p class="expedition-map-note">${t('Натисни на місце, щоб почати урок. Печатка — за складений тест, зірка — за 100%.','Tap a place to start its lesson. Pass a test for a seal; earn a star for 100%.')}</p>
${teamOverview(d)}${activeIsland===1?masteryCollection(1):activeIsland===2?masteryCollection(2)+window.DEUTSCH_GEAR.roster(t,local,teamAwards(2),route):''}
${lighthouseMapStatus(d)}${activeIsland===2&&d.final?.passed?`<p class="lighthouse-status" data-gear-complete>✓ ${t('Рюкзак зібрано · карту маршруту збережено','Backpack packed · route map saved')}</p>`:''}
${marketMapVisit(d)}
${relicCollection()}
<section class="expedition-passport"><h2>${t('Паспорт першовідкривача','Explorer passport')} · ${t('острів','island')} ${activeIsland+1}</h2><div class="expedition-seals">${route.map((r,i)=>`<div class="expedition-seal ${r.earned?'earned':''} ${r.perfect?'perfect':''}" data-expedition-seal="${r.id}"><span>${r.perfect?'★':r.earned?'✓':r.number}</span><small>${local(r.name)}</small></div>`).join('')}</div><p>${t('Печатки зберігаються назавжди. Можна повертатися за 100% — помилки нічого не забирають.','Your seals stay with you. Return for 100% any time — mistakes never take rewards away.')}</p></section>

<details class="journey-more"><summary>${t('Уроки островів та інші теми','Island lessons and more topics')}</summary><ol class="al-route">${stages.map((st,i)=>`<li><button type="button" class="al-route-open" data-al-stage="${i}">${esc(st.title[en()?1:0])}</button></li>`).join('')}</ol></details>`);
root.querySelector('#dailyIslandStart').onclick=()=>dailyStart();const nextIsland=root.querySelector('#gearIslandOpen');if(nextIsland)nextIsland.onclick=()=>journeySelect(2);const celebrate=root.querySelector('#lighthouseCelebrate');if(celebrate)celebrate.onclick=lighthouseScene;const courtesy=root.querySelector('#courtesyOpen');if(courtesy)courtesy.onclick=()=>journeyOpen('courtesy');const greetingOpen=root.querySelector('#greetingOpen');if(greetingOpen)greetingOpen.onclick=()=>journeyOpen('greetings');const sail=root.querySelector('#expeditionSail');if(sail)sail.onclick=foxDeparture;const foxReplay=root.querySelector('#foxConversationReplay');if(foxReplay)foxReplay.onclick=foxConversationOpen;root.querySelectorAll('[data-team-open],[data-award-open],[data-gear-open]').forEach(b=>b.onclick=()=>{const value=b.dataset.teamOpen??b.dataset.awardOpen??b.dataset.gearOpen;journeyOpen(['greetings','courtesy'].includes(value)?value:Number(value))});root.querySelectorAll('[data-resident-open]').forEach(b=>b.onclick=()=>journeyOpen(b.dataset.residentOpen==='courtesy'?'courtesy':Number(b.dataset.residentOpen)));const marketVisit=root.querySelector('#marketVisit');if(marketVisit)marketVisit.onclick=()=>journeyOpen(1);root.querySelectorAll('[data-island]').forEach(b=>b.onclick=()=>journeySelect(Number(b.dataset.island)));root.querySelector('#alStart').onclick=()=>voyagePending?journeyOpen(activeIsland===0?'greetings':'courtesy'):journeyOpen(target);root.querySelectorAll('[data-journey-lesson]').forEach(b=>b.onclick=()=>journeyOpen(Number(b.dataset.journeyLesson)));root.querySelector('#journeyFinal').onclick=()=>journeyOpen(0,true);root.querySelectorAll('[data-al-stage]').forEach(b=>b.onclick=()=>begin(stages[+b.dataset.alStage].cards,stages[+b.dataset.alStage].id,true));const review=root.querySelector('#alReview');if(review)review.onclick=()=>begin(p.due.slice(0,6),null,false);
}catch(e){console.error(e);shell('<p role="alert">'+t('Не вдалося прочитати прогрес. Спробуй перезавантажити сторінку.','Could not read progress. Try reloading the page.')+'</p>')}}

function journeyFinish(){pause();const s=session;s.finished=true;const j=s.journey,c=island(),tests=s.results.filter(r=>r.assessment),total=s.queue.filter(q=>q.assessment).length,correct=tests.filter(r=>r.ok&&!r.skipped).length,pct=Math.round(correct/Math.max(1,total)*100),passed=correct>=Math.ceil(total*.8),d=journeyLoad(),prev=j.final?d.final:d.lessons[j.index],record={passed:!!prev?.passed||passed,best:Math.max(prev?.best||0,pct),last:pct,attempts:(prev?.attempts||0)+1,at:Date.now()};if(j.final)d.final=record;else d.lessons[j.index]=record;profileStorage.setItem(journeyKey,JSON.stringify(d));const missed=s.results.filter(r=>r.assessment&&(!r.ok||r.skipped)),nextIndex=j.index+1;
shell(`${j.island===2?window.DEUTSCH_GEAR.encounter(j,t,local,passed?'success':'encourage',teamMasteryReward(j,pct,prev?.best===100)):''}${teamActor(j)?teamEncounter(j,passed?'success':'encourage',{percent:pct,wasPerfect:prev?.best===100}):''}${j.island===0&&j.final?teamCompassPanel(false):''}${isMarketJourney(j)?marketEncounter(passed?'success':'encourage',{percent:pct,wasPerfect:prev?.best===100}):residentFor(j)?residentEncounter(j,passed?'success':'encourage',{percent:pct,wasPerfect:prev?.best===100}):''}${greetingBridge(j,passed?'success':'encourage')}<div class="journey-result"><span class="journey-result-mark">${passed?'✓':'↻'}</span><div class="tag">${j.final?local(c.finalLabel):local(expeditionStops[j.index].name)}</div>${passed?`<div class="expedition-reward-art">${(isMarketJourney(j)||residentFor(j)||teamActor(j)||j.island===2)&&!j.final?'':expeditionImage(j.final?c.relic:'fox',j.final?'expedition-award-chest':'expedition-award-fox')}</div><p class="expedition-reward-copy">${j.final?local(c.found):j.island===1&&j.index===5?t('Знайомі фрази вже виходять. Застосуй їх у самостійній розмові з Карлом.','You have practised the phrases. Use them in an independent conversation with Karl.'):local(expeditionStops[j.index].after)}</p><span class="expedition-master">${pct===100?'★ '+t(j.final?'Печатка першовідкривача · 100%':'Відзнака майстерності · 100%',j.final?'Explorer seal · 100%':'Mastery award · 100%'):'✓ '+t('Печатку отримано','Seal earned')}</span>`:''}<h1>${passed?(j.final?t('Пригоду завершено!','Adventure complete!'):t('Ще один крок уперед!','Another step forward!')):t('Трохи практики — і спробуємо знову','A little practice, then try again')}</h1><p class="journey-score">${correct} / ${total} · ${pct}%</p><p>${t('Для проходження потрібно щонайменше 80%. Пропущені завдання залишаються незарахованими.','Pass with at least 80%. Skipped tasks do not earn points.')}</p>${missed.length?`<div class="journey-recap"><strong>${t('Варто пригадати','Worth revisiting')}</strong>${[...new Map(missed.map(r=>[r.c.id,r.c])).values()].map(c=>`<div><b lang="de">${esc(c.de)}</b><span>${esc(meaning(c))}</span></div>`).join('')}</div>`:''}<div class="journey-result-buttons"><button class="btn primary" id="journeyNext">${passed&&j.island===2&&j.final?t('До мапи спорядження','Equipment map'):passed&&isMarketJourney(j)&&!window.DEUTSCH_BENNO_CONVERSATION.read()?.completed?t('Поговорити з Бенно','Talk with Benno'):passed&&!j.final&&j.island===1&&j.index===5?(window.DEUTSCH_KARL_CONVERSATION.read()?.completed?t('До фінальної місії','Start the final mission'):t('Поговорити самостійно','Talk independently')):passed&&j.final&&activeIsland===1?t('Засвітити маяк','Light the lighthouse'):passed&&j.final&&activeIsland===0?(foxConversationDone()?t('Вирушити до мешканців','Sail to the residents'):t('Поговорити з Лисом','Talk with Fox')):passed&&!j.final&&nextIndex<journeyLessons.length?t('Наступний урок','Next lesson'):passed&&!j.final?t('До фінальної місії','Start the final mission'):t('Спробувати ще раз','Try again')}</button>${passed&&isMarketJourney(j)&&!window.DEUTSCH_BENNO_CONVERSATION.read()?.completed?`<button type="button" class="btn secondary" id="bennoNextLesson">${t('Наступний урок · Мія','Next lesson · Mia')}</button>`:''}<button class="btn secondary" id="alDone">${passed&&j.final&&j.island===1?t('Повторити фінальну місію','Repeat the final mission'):t('До мапи пригод','Adventure map')}</button></div></div>`);
const bennoNext=root.querySelector('#bennoNextLesson');if(bennoNext)bennoNext.onclick=()=>journeyOpen(2);root.querySelector('#alDone').onclick=()=>passed&&j.final&&j.island===1?journeyOpen(0,true):render();root.querySelector('#journeyNext').onclick=()=>{if(j.island===2&&j.final&&passed){render();return}if(passed&&isMarketJourney(j)&&!window.DEUTSCH_BENNO_CONVERSATION.read()?.completed){bennoConversationOpen()}else if(passed&&!j.final&&j.island===1&&j.index===5){if(window.DEUTSCH_KARL_CONVERSATION.read()?.completed)journeyOpen(0,true);else karlConversationOpen()}else if(passed&&j.final&&activeIsland===1)lighthouseScene();else if(passed&&j.final&&activeIsland===0)foxDeparture();else if(passed&&!j.final&&nextIndex<journeyLessons.length)journeyOpen(nextIndex);else if(passed&&!j.final)journeyOpen(0,true);else journeyOpen(j.index,j.final)}}


