window.DEUTSCH_JOURNEY={get key(){return journeyKey},get lessons(){return journeyLessons},get locations(){return expeditionStops},get island(){return activeIsland},islands:islands.map(c=>({id:c.id,key:c.key,title:c.title})),gearConversation:gearConversationOpen,courtesy:courtesyOpen,conversation:foxConversationOpen,karlConversation:karlConversationOpen,bennoConversation:bennoConversationOpen,test:(index)=>lessonRun({...(typeof index==='string'?{entry:index,index:-1}:{index}),island:activeIsland,final:false},'test'),repeat:index=>shadowingOpen({...(typeof index==='string'?{entry:index,index:-1}:{index}),island:activeIsland}),trainingState:trainingState,mastery:teamAwards,route:routeProgress,greetings:greetingsOpen,select:journeySelect,progress:islandProgress,open:journeyOpen,queue:journeyQueue,load:journeyLoad,map:journeyMap,rewards:expeditionRewards};
